// ❌ 고정 대기 — 느린 기계에서 깨지고, 빠른 기계에선 낭비
await sleep(300);
expect(화면.텍스트()).toBe('저장됨');

// ✅ 조건 대기 — 조건이 될 때까지(타임아웃 상한 안에서)
await waitFor(() => 화면.텍스트() === '저장됨', { timeout: 5000 });
//   조건 충족 즉시 진행(빠름) · 안 되면 5초까지 기다림(느려도 견딤)

// 테스트 도구의 조건 대기 (예)
await expect(page.getByText('저장됨')).toBeVisible();  // Playwright: 자동 재시도
await waitFor(() => screen.getByText('저장됨'));       // Testing Library
// 「시간」이 아니라 「상태」를 기다린다 — 타이밍 깜빡임 대부분 제거

// ❌ 공유 상태에 의존 — 순서·병렬에서 깨짐
test('A', () => { db.createUser('alice'); ... });
test('B', () => { expect(db.getUser('alice')).toBeDefined(); }); // A 에 의존!

// ✅ 각 테스트가 독립 — 자기 데이터 생성 + 정리
beforeEach(() => { db.reset(); });               // 상태 초기화
test('B', () => {
  const user = db.createUser('bob-' + uniqueId()); // 자기 것 생성(고유)
  expect(db.getUser(user.id)).toBeDefined();
});
afterEach(() => { db.cleanup(); });              // 정리(안 남김)

// 순서를 무작위화해 숨은 의존을 드러내라: jest --random-order

// ❌ 시간·랜덤이 코드에 박힘 — 테스트에서 제어 불가(깜빡임)
function makeId() { return Date.now() + '-' + Math.random(); }

// ✅ 이음매 — 시간·랜덤을 밖에서 주입 (테스트에서 고정)
function makeId(now = Date.now, rand = Math.random) {
  return now() + '-' + rand();
}
// 테스트: 고정값 주입 → 결정적
makeId(() => 1700000000000, () => 0.5);  // 항상 같은 결과

// 시간 라이브러리의 고정 (예)
jest.useFakeTimers().setSystemTime(new Date('2026-01-01'));  // 고정 시각
// 네트워크는 mock: msw·nock 으로 외부 응답을 고정
